/* Scratch Firebird 4 schema for the live field-repository tests. @DB@ is replaced by the path of the scratch file. */
CREATE DATABASE '@DB@' USER SYSDBA;
CREATE DOMAIN D_NAME AS VARCHAR(40) CHARACTER SET WIN1252 DEFAULT 'x' NOT NULL;
CREATE DOMAIN D_POS AS INTEGER CHECK (VALUE > 0);
CREATE DOMAIN D_BIG AS INT128;
CREATE DOMAIN D_DEC AS DECFLOAT(16);
CREATE TABLE PARENT (
  ID INTEGER NOT NULL,
  NAME D_NAME,
  CODE CHAR(3) NOT NULL,
  BIGV D_BIG,
  DECV D_DEC,
  QTY D_POS,
  INLN INTEGER NOT NULL,
  INLD VARCHAR(10) DEFAULT 'abc',
  CONSTRAINT PK_PARENT PRIMARY KEY (ID),
  CONSTRAINT UQ_CODE UNIQUE (CODE),
  CONSTRAINT CK_ID CHECK (ID > 0));
CREATE TABLE CHILD (
  ID INTEGER NOT NULL,
  PID INTEGER,
  CONSTRAINT PK_CHILD PRIMARY KEY (ID),
  CONSTRAINT FK_CHILD_PARENT FOREIGN KEY (PID) REFERENCES PARENT (ID) ON DELETE CASCADE ON UPDATE SET NULL);
CREATE GENERATOR GEN_X;
COMMIT;
